// Biotechnology: Principles and Processes — generated by Claude (no source PDF).
// Covers the two core techniques (genetic engineering, bioprocess technology),
// tools of rDNA technology (restriction enzymes, vectors, competent hosts), the
// full process (isolation, cutting, amplification via PCR, ligation, transfer,
// culturing, downstream processing), and bioreactors.

export const BIOTECH_PRINCIPLES = [
  // ---- MCQ ----
  { id: 'btp-1', type: 'mcq', question: 'Modern biotechnology is generally described as resting on two core techniques:', options: ['Tissue culture and hybridisation', 'Genetic engineering and maintenance of sterile ambience in bioprocess technology', 'Selective breeding and grafting', 'Pasteurisation and fermentation only'], correctIndex: 1, explanation: 'Biotechnology combines genetically modifying organisms (genetic engineering) with maintaining contamination-free conditions to scale up production (bioprocess engineering).', difficulty: 'easy' },
  { id: 'btp-2', type: 'mcq', question: 'Restriction endonucleases were discovered through research on why:', options: ['Bacteria could not be cultured in the lab', 'Bacteriophages could not multiply within certain bacterial strains', 'Plants resist certain herbicides', 'Human cells reject foreign DNA'], correctIndex: 1, explanation: 'Restriction enzymes were discovered by studying bacteria that resist bacteriophage infection by cutting up the invading phage DNA.', difficulty: 'medium' },
  { id: 'btp-3', type: 'mcq', question: 'The Nobel Prize for the discovery of restriction endonucleases was awarded to:', options: ['Watson and Crick', 'Hamilton Smith, Werner Arber, and Daniel Nathans', 'Har Gobind Khorana', 'Kary Mullis'], correctIndex: 1, explanation: 'Smith, Arber, and Nathans received the 1978 Nobel Prize for discovering and characterising restriction enzymes.', difficulty: 'medium' },
  { id: 'btp-4', type: 'mcq', question: 'Restriction endonucleases cut DNA:', options: ['At random locations anywhere in the molecule', 'At specific palindromic recognition sequences', 'Only at the 5\' end of the molecule', 'Only within RNA-DNA hybrids'], correctIndex: 1, explanation: 'Restriction enzymes recognise specific palindromic base sequences and cut precisely at or near them.', difficulty: 'easy' },
  { id: 'btp-5', type: 'mcq', question: 'A palindromic DNA sequence is one that:', options: ['Reads the same on both strands when read in the 5\' to 3\' direction', 'Contains no repeating bases', 'Is found only in prokaryotes', 'Cannot be cut by any enzyme'], correctIndex: 0, explanation: 'A palindrome in DNA reads identically 5\'→3\' on both complementary strands, e.g., GAATTC.', difficulty: 'medium' },
  { id: 'btp-6', type: 'mcq', question: 'The restriction enzyme EcoRI is obtained from:', options: ['Escherichia coli', 'Bacillus thuringiensis', 'Agrobacterium tumefaciens', 'Thermus aquaticus'], correctIndex: 0, explanation: 'EcoRI is derived from Escherichia coli, as reflected in its name.', difficulty: 'medium' },
  { id: 'btp-7', type: 'mcq', question: 'DNA fragments produced by restriction digestion are typically separated and visualised using:', options: ['PCR amplification only', 'Gel electrophoresis', 'Centrifugation alone', 'Chromatography'], correctIndex: 1, explanation: 'Gel electrophoresis separates DNA fragments by size as they migrate through a gel matrix under an electric field.', difficulty: 'easy' },
  { id: 'btp-8', type: 'mcq', question: 'During agarose gel electrophoresis, DNA fragments (being negatively charged) migrate towards the:', options: ['Cathode (negative electrode)', 'Anode (positive electrode)', 'Centre of the gel, staying stationary', 'Top of the gel only'], correctIndex: 1, explanation: 'DNA is negatively charged due to its phosphate backbone, so it moves towards the positively charged anode.', difficulty: 'medium' },
  { id: 'btp-9', type: 'mcq', question: 'The dye commonly used to stain DNA fragments in a gel so they become visible under UV light is:', options: ['Safranin', 'Ethidium bromide', 'Methylene blue', 'Eosin'], correctIndex: 1, explanation: 'Ethidium bromide intercalates into DNA and fluoresces under UV light, making bands visible.', difficulty: 'easy' },
  { id: 'btp-10', type: 'mcq', question: "The process of cutting out a visualised DNA band from a gel and extracting the DNA from it is called:", options: ['Ligation', 'Elution', 'Transformation', 'Denaturation'], correctIndex: 1, explanation: 'Elution is the recovery/extraction of separated DNA fragments from a gel slice.', difficulty: 'medium' },
  { id: 'btp-11', type: 'mcq', question: 'A self-replicating small circular DNA molecule commonly used to carry foreign DNA into a host bacterium is called a:', options: ['Ribosome', 'Plasmid vector', 'Lysosome', 'Golgi vesicle'], correctIndex: 1, explanation: 'Plasmids are widely used as cloning vectors since they replicate independently of the bacterial chromosome.', difficulty: 'easy' },
  { id: 'btp-12', type: 'mcq', question: 'pBR322, a classic cloning vector, includes which of the following features?', options: ['An origin of replication (ori), selectable marker genes, and cloning sites', 'A functioning nucleus', 'Chlorophyll-producing genes', 'A cell wall'], correctIndex: 0, explanation: 'pBR322 has an ori, antibiotic-resistance marker genes (ampR, tetR), and unique restriction sites for cloning.', difficulty: 'medium' },
  { id: 'btp-13', type: 'mcq', question: 'The sequence in a vector from which DNA replication begins, also controlling the copy number of the linked DNA, is the:', options: ['Selectable marker', 'Origin of replication (ori)', 'Cloning site', 'Insertional site'], correctIndex: 1, explanation: 'The origin of replication (ori) is where replication starts and determines how many copies of the plasmid are maintained per cell.', difficulty: 'medium' },
  { id: 'btp-14', type: 'mcq', question: 'A gene (such as one conferring antibiotic resistance) used to identify and eliminate non-transformed host cells is called a:', options: ['Reporter gene', 'Selectable marker', 'Structural gene', 'Regulatory gene'], correctIndex: 1, explanation: 'Selectable markers (e.g., ampicillin/tetracycline resistance genes) help distinguish transformants from non-transformants.', difficulty: 'medium' },
  { id: 'btp-15', type: 'mcq', question: 'When a foreign gene is inserted into one of the antibiotic-resistance genes of a vector, inactivating it, this screening method is called:', options: ['Blue-white screening only', 'Insertional inactivation', 'Restriction mapping', 'Gene silencing'], correctIndex: 1, explanation: 'Inserting DNA within a marker gene inactivates it, allowing recombinants to be distinguished based on the loss of that marker function.', difficulty: 'medium' },
  { id: 'btp-16', type: 'mcq', question: 'Bacterial cells must be made "competent" before taking up foreign plasmid DNA. A common method to achieve this uses:', options: ['UV irradiation only', 'Treatment with a divalent cation like CaCl2, followed by a brief heat shock', 'Boiling the cells', 'Freezing at -196°C only'], correctIndex: 1, explanation: 'CaCl2 treatment increases cell wall/membrane permeability, and a subsequent heat shock (e.g., 42°C) helps DNA enter the cell.', difficulty: 'medium' },
  { id: 'btp-17', type: 'mcq', question: 'The Ti plasmid, used as a natural vector for gene transfer into dicot plants, is derived from:', options: ['Escherichia coli', 'Agrobacterium tumefaciens', 'Bacillus thuringiensis', 'Salmonella typhimurium'], correctIndex: 1, explanation: 'Agrobacterium tumefaciens carries the Ti (tumour-inducing) plasmid, which is disarmed and used to deliver genes into plant cells.', difficulty: 'medium' },
  { id: 'btp-18', type: 'mcq', question: 'Directly injecting foreign DNA into the nucleus of an animal cell is a technique known as:', options: ['Biolistics', 'Micro-injection', 'Electroporation only', 'Transduction'], correctIndex: 1, explanation: 'Micro-injection physically delivers DNA into the nucleus, commonly used in animal cell transformation.', difficulty: 'medium' },
  { id: 'btp-19', type: 'mcq', question: 'The "gene gun" or biolistic method of gene transfer, often used in plants, works by:', options: ['Injecting DNA with a fine needle', 'Bombarding cells with high-velocity DNA-coated microparticles', 'Using a virus to carry DNA', 'Soaking seeds in a DNA solution'], correctIndex: 1, explanation: 'Biolistics propels DNA-coated gold/tungsten particles into plant cells at high velocity.', difficulty: 'medium' },
  { id: 'btp-20', type: 'mcq', question: 'Which vector class has historically been used to deliver genes into animal cells, exploiting its natural ability to insert genetic material into a host genome?', options: ['Plasmids only', 'Disarmed retroviruses', 'Ti plasmid', 'Restriction enzymes'], correctIndex: 1, explanation: 'Disarmed retroviruses can be used as vectors, integrating desired genes into the host genome as part of their normal life cycle.', difficulty: 'medium' },
  { id: 'btp-21', type: 'mcq', question: 'The first step of recombinant DNA technology, before any cutting or ligation can occur, is:', options: ['Amplification of the gene by PCR', 'Isolation of the genetic material (DNA)', 'Culturing the host cell', 'Downstream processing'], correctIndex: 1, explanation: 'DNA must first be isolated in pure form before it can be manipulated by restriction enzymes.', difficulty: 'easy' },
  { id: 'btp-22', type: 'mcq', question: 'In the process of recombinant DNA technology, cutting DNA at specific locations is achieved using:', options: ['DNA ligase', 'Restriction endonucleases', 'RNA polymerase', 'Reverse transcriptase'], correctIndex: 1, explanation: 'Restriction endonucleases perform the precise cutting step in rDNA technology.', difficulty: 'easy' },
  { id: 'btp-23', type: 'mcq', question: 'The enzyme responsible for joining (sealing) a foreign DNA fragment with a vector during ligation is:', options: ['Restriction endonuclease', 'DNA ligase', 'DNA polymerase', 'Helicase'], correctIndex: 1, explanation: 'DNA ligase seals the phosphodiester backbone, joining the insert and vector into one recombinant molecule.', difficulty: 'easy' },
  { id: 'btp-24', type: 'mcq', question: 'The Polymerase Chain Reaction (PCR) is primarily used to:', options: ['Cut DNA at specific sites', 'Amplify a specific gene/DNA sequence into many copies', 'Separate DNA fragments by size', 'Insert a gene permanently into a chromosome'], correctIndex: 1, explanation: 'PCR exponentially amplifies a target DNA sequence using repeated cycles of denaturation, annealing, and extension.', difficulty: 'easy' },
  { id: 'btp-25', type: 'mcq', question: 'The heat-stable DNA polymerase commonly used in PCR, allowing repeated heating without denaturing the enzyme, is isolated from:', options: ['Escherichia coli', 'Thermus aquaticus', 'Agrobacterium tumefaciens', 'Saccharomyces cerevisiae'], correctIndex: 1, explanation: 'Taq polymerase, from the thermophilic bacterium Thermus aquaticus, remains stable through PCR\'s repeated high-temperature steps.', difficulty: 'medium' },
  { id: 'btp-26', type: 'mcq', question: 'The three basic steps repeated in each cycle of PCR are:', options: ['Transcription, translation, replication', 'Denaturation, annealing, extension', 'Ligation, transformation, selection', 'Isolation, elution, amplification'], correctIndex: 1, explanation: 'Each PCR cycle denatures the DNA, anneals primers, and extends new strands using the polymerase.', difficulty: 'easy' },
  { id: 'btp-27', type: 'mcq', question: 'Short single-stranded DNA sequences that bind to the template DNA and initiate DNA synthesis in PCR are called:', options: ['Primers', 'Vectors', 'Ligands', 'Probes only'], correctIndex: 0, explanation: 'Primers are short synthetic oligonucleotides that anneal to the template, providing a starting point for polymerase activity.', difficulty: 'easy' },
  { id: 'btp-28', type: 'mcq', question: 'After a desired gene product has been synthesised biologically, the series of processes involved in separating and purifying it for the market is collectively called:', options: ['Upstream processing', 'Downstream processing', 'Insertional inactivation', 'Bioremediation'], correctIndex: 1, explanation: 'Downstream processing includes separation, purification, and formulation of the product with preservatives, followed by quality testing.', difficulty: 'medium' },
  { id: 'btp-29', type: 'mcq', question: 'A large vessel in which raw materials are biologically converted into specific products using microbial/plant/animal cells is called a:', options: ['Centrifuge', 'Bioreactor', 'Gel tank', 'Spectrophotometer'], correctIndex: 1, explanation: 'Bioreactors provide optimal conditions (oxygen, temperature, pH, substrate) for large-scale cell/enzyme-based production.', difficulty: 'easy' },
  { id: 'btp-30', type: 'mcq', question: 'A commonly used bioreactor design with an agitator system to keep contents mixed and oxygen evenly available is the:', options: ['Sparged stirred-tank bioreactor', 'Static flask culture', 'Petri dish system', 'Test tube culture'], correctIndex: 0, explanation: 'The stirred-tank bioreactor (often sparged for aeration) is a standard design for large-scale, well-mixed, aerobic cultures.', difficulty: 'medium' },
  { id: 'btp-31', type: 'mcq', question: 'The part of a stirred-tank bioreactor responsible for keeping the culture well mixed and providing uniform oxygen availability is the:', options: ['Agitator system', 'Foam-control system', 'Sampling port', 'Vector cassette'], correctIndex: 0, explanation: 'The agitator (with an oxygen delivery system) mixes and aerates the culture uniformly throughout the vessel.', difficulty: 'medium' },
  { id: 'btp-32', type: 'mcq', question: 'Why is it important for a bioreactor to maintain a low-oxygen or contamination-free environment appropriate to the specific culture?', options: ['To maximise growth of unwanted contaminants', 'To ensure the desired organism/enzyme performs optimally without competition or interference', 'Because sterility is not important in bioprocessing', 'Because oxygen always inhibits all biological reactions'], correctIndex: 1, explanation: 'Maintaining sterile, suitable conditions ensures the desired biological system (not contaminants) drives the intended reaction/production.', difficulty: 'medium' },
  { id: 'btp-33', type: 'mcq', question: 'Which of these is an essential requirement before restriction digestion products can be visualised on a gel?', options: ['The DNA must first be radiolabelled', 'The gel must be stained with a fluorescent dye like ethidium bromide and exposed to UV light', 'The DNA must first be sequenced', 'The gel must be boiled after the run'], correctIndex: 1, explanation: 'Without staining and UV exposure, separated DNA fragments in the gel remain invisible to the naked eye.', difficulty: 'medium' },
  { id: 'btp-34', type: 'mcq', question: 'A cloning vector is chosen partly for having only ONE recognition site for a given restriction enzyme within a non-essential region — why?', options: ['So the vector cannot be cut at all', 'So that inserting foreign DNA at that site does not disrupt other essential vector functions like ori or selectable markers', 'To make the vector resistant to all enzymes', 'To prevent bacterial uptake of the vector'], correctIndex: 1, explanation: 'A single, well-placed restriction site allows insertion of foreign DNA without damaging essential vector elements.', difficulty: 'hard' },
  { id: 'btp-35', type: 'mcq', question: 'Which of the following best explains why bacterial cells are treated with CaCl2 before a heat shock in the transformation step?', options: ['To kill any bacteria that are not competent', 'To make the cell membrane more permeable to DNA uptake', 'To provide nutrients for bacterial growth', 'To stain the DNA for visualisation'], correctIndex: 1, explanation: 'CaCl2 destabilises the cell membrane, and the subsequent heat shock creates a transient opening allowing DNA to enter.', difficulty: 'medium' },
  { id: 'btp-36', type: 'mcq', question: 'Which of these is NOT typically a component of the "tools" of recombinant DNA technology?', options: ['Restriction enzymes', 'Cloning vectors', 'A suitable host organism', 'Photosynthetic pigment complexes'], correctIndex: 3, explanation: 'Photosynthetic pigments are unrelated; the essential tools are restriction enzymes, vectors, and a competent host.', difficulty: 'easy' },
  { id: 'btp-37', type: 'mcq', question: 'A key reason recombinant DNA technology became feasible only after the discovery of restriction enzymes is that these enzymes:', options: ['Allow DNA to be replicated without a template', 'Allow precise, reproducible cutting of DNA at defined sequences, enabling controlled gene isolation', 'Destroy all foreign DNA in a cell', 'Convert RNA into DNA'], correctIndex: 1, explanation: 'Precise, sequence-specific cutting is what allows scientists to reliably isolate and manipulate specific genes.', difficulty: 'medium' },
  { id: 'btp-38', type: 'mcq', question: 'In agarose gel electrophoresis, smaller DNA fragments move:', options: ['Slower through the gel than larger fragments', 'Faster through the gel than larger fragments', 'At the same speed as larger fragments always', 'Not at all through the gel'], correctIndex: 1, explanation: 'Smaller DNA fragments encounter less resistance from the gel matrix and migrate faster than larger ones.', difficulty: 'easy' },
  { id: 'btp-39', type: 'mcq', question: 'Recombinant DNA technology requires a "host" organism mainly to:', options: ['Provide the machinery to replicate/express the introduced gene', 'Provide restriction enzymes for cutting', 'Act as the source of the gene of interest always', 'Serve only as a storage container for DNA'], correctIndex: 0, explanation: 'The host organism (like E. coli) provides the cellular machinery to replicate the vector and express the inserted gene.', difficulty: 'medium' },
  { id: 'btp-40', type: 'mcq', question: 'Quality control testing during downstream processing of a biotechnology product typically involves checking for:', options: ['Only the colour of the final product', 'Product purity, safety, and consistency before it reaches the market', 'The taste of the product only', 'The size of the bioreactor used'], correctIndex: 1, explanation: 'Rigorous quality control ensures the final product meets safety and consistency standards for use.', difficulty: 'medium' },
  { id: 'btp-41', type: 'mcq', question: 'Bacteria naturally produce restriction enzymes primarily as a means of:', options: ['Producing energy for metabolism', 'Defending themselves against invading bacteriophage DNA', 'Synthesising proteins', 'Repairing their own damaged DNA'], correctIndex: 1, explanation: "Restriction enzymes act as a bacterium's defence system, cutting up foreign phage DNA that enters the cell.", difficulty: 'medium' },
  { id: 'btp-42', type: 'mcq', question: "A bacterium's own DNA is typically protected from its own restriction enzymes by:", options: ['Having no recognition sequences at all', 'Chemical modification (e.g., methylation) of its own DNA at those recognition sites', 'Keeping the enzyme inactive at all times', 'Storing its DNA outside the cell'], correctIndex: 1, explanation: "Methylation of the host's own DNA at recognition sites prevents the restriction enzyme from cutting its own genome.", difficulty: 'hard' },
  { id: 'btp-43', type: 'mcq', question: 'Which of the following is an example of a selectable marker commonly used in plasmid vectors like pBR322?', options: ['Green fluorescent protein only', 'Ampicillin resistance (ampR) gene', 'A gene for chlorophyll synthesis', 'A gene encoding insulin'], correctIndex: 1, explanation: 'ampR (and tetR) are classic antibiotic-resistance selectable marker genes used in pBR322.', difficulty: 'medium' },
  { id: 'btp-44', type: 'mcq', question: 'Why might scientists prefer a vector with more than one unique restriction site available for cloning, arranged closely together?', options: ['To make a "polylinker/multiple cloning site" offering flexibility in choice of enzyme for insertion', 'To make cloning impossible', 'To ensure the vector cannot replicate', 'To eliminate the need for a host organism'], correctIndex: 0, explanation: 'A multiple cloning site (polylinker) gives flexibility to use different restriction enzymes depending on the insert DNA ends.', difficulty: 'hard' },
  { id: 'btp-45', type: 'mcq', question: 'Which statement correctly distinguishes exonucleases from endonucleases?', options: ['Exonucleases cut DNA only at internal specific sequences; endonucleases cut only from the ends', 'Endonucleases cut DNA at specific internal sites; exonucleases remove nucleotides from the ends of the DNA strand', 'Both cut DNA only from the middle', 'There is no functional difference between them'], correctIndex: 1, explanation: 'Endonucleases cut within the DNA strand at specific sites, while exonucleases progressively remove nucleotides from the strand ends.', difficulty: 'medium' },
  { id: 'btp-46', type: 'mcq', question: "PCR's exponential amplification means that after 'n' cycles, a single starting DNA molecule can theoretically yield approximately:", options: ['n copies', '2n copies', '2^n copies', 'n^2 copies'], correctIndex: 2, explanation: 'Each PCR cycle doubles the DNA amount, so after n cycles the theoretical yield is 2^n copies.', difficulty: 'medium' },
  { id: 'btp-47', type: 'mcq', question: 'Which of these best describes the role of a "template" in PCR?', options: ['The primer sequence used to detect contamination', 'The original DNA strand that serves as the pattern to be copied', 'The final purified protein product', 'The bioreactor vessel itself'], correctIndex: 1, explanation: 'The template is the DNA strand from which new complementary strands are synthesised during PCR.', difficulty: 'medium' },
  { id: 'btp-48', type: 'mcq', question: 'Which of the following would be an appropriate host organism commonly used for basic recombinant DNA cloning experiments?', options: ['Escherichia coli', 'Homo sapiens', 'Panthera leo', 'Solanum tuberosum (as a direct host bacterium)'], correctIndex: 0, explanation: 'E. coli is the classic, well-characterised bacterial host widely used for cloning experiments.', difficulty: 'easy' },
  { id: 'btp-49', type: 'mcq', question: 'The term "cloning vector" refers to a DNA molecule that:', options: ['Cannot replicate inside a host', 'Is used to carry a foreign DNA fragment into a host cell and replicate it there', 'Is always a virus that kills the host', 'Only functions in plant cells'], correctIndex: 1, explanation: 'A cloning vector carries and replicates inserted foreign DNA within a suitable host cell.', difficulty: 'easy' },
  { id: 'btp-50', type: 'mcq', question: 'The overall goal of recombinant DNA technology, from isolation of a gene to downstream processing, is ultimately to:', options: ['Simply observe DNA under a microscope', 'Produce a desired biological product (e.g., protein) in large, purified quantities', 'Destroy unwanted genes permanently', 'Only classify organisms taxonomically'], correctIndex: 1, explanation: 'The entire rDNA pipeline is designed to reliably manufacture a useful biological product at scale.', difficulty: 'easy' },

  // ---- Assertion-Reason ----
  { id: 'btp-ar-1', type: 'assertion-reason', question: 'Assertion (A): Restriction enzymes are essential tools of genetic engineering.\nReason (R): They allow DNA to be cut precisely at specific, reproducible sequences.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'This precise, reproducible cutting ability is exactly why restriction enzymes are indispensable to genetic engineering.', difficulty: 'medium' },
  { id: 'btp-ar-2', type: 'assertion-reason', question: 'Assertion (A): DNA fragments move towards the cathode during gel electrophoresis.\nReason (R): DNA is a negatively charged molecule due to its phosphate backbone.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'DNA actually moves towards the anode (positive electrode), not the cathode, so A is false; R correctly states why (negative charge is attracted to the positive electrode).', difficulty: 'medium' },
  { id: 'btp-ar-3', type: 'assertion-reason', question: 'Assertion (A): A plasmid used as a cloning vector must have an origin of replication.\nReason (R): The origin of replication allows the plasmid (and any DNA linked to it) to replicate independently within the host cell.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Independent replication driven by ori is exactly why a functional origin of replication is essential for any cloning vector.', difficulty: 'medium' },
  { id: 'btp-ar-4', type: 'assertion-reason', question: 'Assertion (A): Selectable marker genes help identify and eliminate transformed cells.\nReason (R): Selectable markers, such as antibiotic resistance genes, allow non-transformed cells to be distinguished and removed, keeping only transformants.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Selectable markers actually help identify and eliminate NON-transformed cells (not transformed ones), so A is false; R correctly describes their true purpose.', difficulty: 'medium' },
  { id: 'btp-ar-5', type: 'assertion-reason', question: 'Assertion (A): Insertional inactivation is used as a screening method for recombinants.\nReason (R): Insertion of foreign DNA into a marker gene disrupts (inactivates) that gene\'s function, providing a detectable change.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'The loss of marker gene function upon insertion is exactly what makes insertional inactivation useful for spotting recombinants.', difficulty: 'medium' },
  { id: 'btp-ar-6', type: 'assertion-reason', question: 'Assertion (A): E. coli cells readily take up foreign plasmid DNA under normal conditions without any special treatment.\nReason (R): Bacterial cells must usually be made "competent" (e.g., via CaCl2 and heat shock) to efficiently take up foreign DNA.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Under normal conditions, uptake is inefficient — special competence treatment is needed (A is false); R correctly states why this treatment is required.', difficulty: 'medium' },
  { id: 'btp-ar-7', type: 'assertion-reason', question: 'Assertion (A): The Ti plasmid of Agrobacterium tumefaciens is used, in a disarmed form, as a vector for plant genetic engineering.\nReason (R): Agrobacterium naturally transfers a portion of its Ti plasmid into plant cells as part of its infection process.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Agrobacterium's natural gene-transfer ability into plant cells is exactly why its Ti plasmid, once disarmed, is repurposed as a plant vector.", difficulty: 'medium' },
  { id: 'btp-ar-8', type: 'assertion-reason', question: 'Assertion (A): PCR requires a heat-stable DNA polymerase.\nReason (R): PCR involves repeated cycles of high-temperature denaturation, which would destroy a typical, non-thermostable enzyme.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Since PCR repeatedly heats the reaction to denature DNA, only a heat-stable polymerase like Taq survives to keep functioning.', difficulty: 'medium' },
  { id: 'btp-ar-9', type: 'assertion-reason', question: 'Assertion (A): Primers used in PCR are long, double-stranded DNA molecules.\nReason (R): Primers must be short, single-stranded oligonucleotides complementary to the template ends.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Primers are actually short and single-stranded, not long and double-stranded (A is false); R correctly describes real primer characteristics.', difficulty: 'medium' },
  { id: 'btp-ar-10', type: 'assertion-reason', question: 'Assertion (A): Downstream processing is unnecessary once a biotechnology product has been synthesised inside a bioreactor.\nReason (R): Products must typically be separated, purified, and formulated before they can be marketed.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Downstream processing IS necessary (A is false); R correctly explains why — raw synthesised product needs purification and formulation before use.', difficulty: 'medium' },
  { id: 'btp-ar-11', type: 'assertion-reason', question: 'Assertion (A): A bioreactor provides optimal conditions such as temperature, pH, and oxygen for large-scale biological production.\nReason (R): Maintaining these optimal conditions maximises the yield of the desired product from the culture.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Providing and controlling optimal conditions is exactly why bioreactors help maximise product yield at scale.', difficulty: 'medium' },
  { id: 'btp-ar-12', type: 'assertion-reason', question: 'Assertion (A): The stirred-tank bioreactor has an agitator system.\nReason (R): The agitator helps ensure uniform mixing and oxygen availability throughout the culture.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: "Uniform mixing/aeration is exactly the function the agitator serves in a stirred-tank bioreactor.", difficulty: 'easy' },
  { id: 'btp-ar-13', type: 'assertion-reason', question: 'Assertion (A): Gel electrophoresis alone is sufficient to determine the exact nucleotide sequence of a DNA fragment.\nReason (R): Gel electrophoresis separates DNA fragments only by their size, not by their sequence content.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Gel electrophoresis cannot reveal sequence, only fragment size (A is false); R correctly explains this limitation.', difficulty: 'medium' },
  { id: 'btp-ar-14', type: 'assertion-reason', question: "Assertion (A): Bacteria protect their own DNA from their restriction enzymes.\nReason (R): Bacterial DNA is chemically modified, often by methylation, at the recognition sequences that the enzyme would otherwise cut.", options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Methylation of the host\'s own recognition sites is exactly the mechanism that protects bacterial DNA from its own restriction enzymes.', difficulty: 'hard' },
  { id: 'btp-ar-15', type: 'assertion-reason', question: 'Assertion (A): The biolistic (gene gun) method is generally used to introduce genes into animal cells rather than plant cells.\nReason (R): Plant cell walls make DNA delivery by simple injection difficult, so high-velocity particle bombardment is often preferred for plants.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Biolistics is actually more associated with PLANT cells (not animal cells), so A is false; R correctly explains why this method suits plants (rigid cell walls).', difficulty: 'medium' },
  { id: 'btp-ar-16', type: 'assertion-reason', question: 'Assertion (A): PCR can amplify even a single molecule of DNA into billions of copies.\nReason (R): PCR uses an exponential doubling process across repeated cycles.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Exponential (2^n) doubling per cycle is exactly why PCR can generate billions of copies from a single template molecule.', difficulty: 'medium' },
  { id: 'btp-ar-17', type: 'assertion-reason', question: 'Assertion (A): A cloning vector needs at least one unique restriction site for practical use.\nReason (R): A unique site allows a foreign DNA fragment to be inserted at a defined location without disrupting essential vector functions.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 0, explanation: 'Preserving essential vector elements while allowing controlled insertion is exactly why a unique restriction site matters.', difficulty: 'medium' },
  { id: 'btp-ar-18', type: 'assertion-reason', question: 'Assertion (A): Micro-injection is a technique exclusively used for bacterial transformation.\nReason (R): Micro-injection involves directly injecting DNA into the nucleus of a cell, most often used with animal cells/eggs.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Micro-injection is used with animal cells (like fertilised eggs), not bacterial transformation (A is false); R correctly describes the actual technique and its typical use.', difficulty: 'medium' },
  { id: 'btp-ar-19', type: 'assertion-reason', question: 'Assertion (A): Ethidium bromide staining allows DNA bands in a gel to be seen under normal white light.\nReason (R): Ethidium bromide-bound DNA fluoresces when exposed to ultraviolet (UV) light.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: 'Visualisation requires UV light, not normal white light (A is false); R correctly describes the actual fluorescence mechanism under UV.', difficulty: 'medium' },
  { id: 'btp-ar-20', type: 'assertion-reason', question: 'Assertion (A): The choice of host organism in recombinant DNA technology has no effect on how well a foreign gene is expressed.\nReason (R): Different host cells (bacterial, plant, animal) have different cellular machinery and post-translational modification capabilities.', options: ['Both A and R are true, and R is the correct explanation of A', 'Both A and R are true, but R is NOT the correct explanation of A', 'A is true, but R is false', 'A is false, but R is true'], correctIndex: 3, explanation: "Host choice DOES significantly affect gene expression/product quality (A is false); R correctly explains why, given differing cellular machinery across host types.", difficulty: 'hard' },

  // ---- Statement-based ----
  { id: 'btp-st-1', type: 'statement', question: 'Statement I: Restriction enzymes recognise and cut DNA at palindromic sequences.\nStatement II: All restriction enzymes leave sticky ends after cutting DNA.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — some restriction enzymes leave sticky ends, while others produce blunt ends.', difficulty: 'medium' },
  { id: 'btp-st-2', type: 'statement', question: 'Statement I: Gel electrophoresis separates DNA fragments based on their electric charge differences.\nStatement II: Gel electrophoresis separates DNA fragments based on their size.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: "Statement I is incorrect — all DNA fragments have essentially the same charge-to-mass ratio; Statement II correctly identifies size as the separating factor.", difficulty: 'medium' },
  { id: 'btp-st-3', type: 'statement', question: 'Statement I: pBR322 contains genes for both ampicillin and tetracycline resistance.\nStatement II: These resistance genes serve as selectable markers to identify transformed bacteria.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements accurately describe key features of the pBR322 vector.', difficulty: 'medium' },
  { id: 'btp-st-4', type: 'statement', question: 'Statement I: Competent host cells are prepared by treatment with a divalent cation followed by heat shock.\nStatement II: This treatment makes it easier for DNA to enter through the cell membrane pores.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the standard bacterial transformation procedure and its rationale.', difficulty: 'medium' },
  { id: 'btp-st-5', type: 'statement', question: "Statement I: The Ti plasmid is used only to introduce genes into animal cells.\nStatement II: Disarmed Agrobacterium vectors are commonly used to introduce genes into dicot plants.", options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — the Ti plasmid is used for PLANT (not animal) cells; Statement II correctly describes its actual use.', difficulty: 'medium' },
  { id: 'btp-st-6', type: 'statement', question: 'Statement I: PCR requires primers complementary to the sequences flanking the region to be amplified.\nStatement II: PCR does not require any DNA polymerase enzyme.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — PCR absolutely requires a (thermostable) DNA polymerase to synthesise new strands.', difficulty: 'medium' },
  { id: 'btp-st-7', type: 'statement', question: 'Statement I: Taq polymerase is preferred in PCR because it remains active despite repeated heating.\nStatement II: Taq polymerase is derived from a thermophilic bacterium.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe why Taq polymerase (from Thermus aquaticus) suits the PCR process.', difficulty: 'medium' },
  { id: 'btp-st-8', type: 'statement', question: 'Statement I: Downstream processing includes separation and purification of the product.\nStatement II: Downstream processing also involves formulation with suitable preservatives and quality control testing.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe components of downstream processing.', difficulty: 'medium' },
  { id: 'btp-st-9', type: 'statement', question: 'Statement I: Bioreactors allow large-scale production under carefully controlled conditions.\nStatement II: Bioreactors are only used for producing antibiotics and have no other applications.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — bioreactors are used for a wide range of products, not just antibiotics (enzymes, hormones, recombinant proteins, etc.).', difficulty: 'medium' },
  { id: 'btp-st-10', type: 'statement', question: 'Statement I: A stirred-tank bioreactor typically has an agitator and an oxygen delivery system.\nStatement II: These features help maintain homogenous conditions throughout the culture.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe stirred-tank bioreactor design and purpose.', difficulty: 'medium' },
  { id: 'btp-st-11', type: 'statement', question: 'Statement I: Insertional inactivation always involves inserting foreign DNA into the origin of replication.\nStatement II: Insertional inactivation typically involves inserting foreign DNA into a selectable marker gene.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — insertion into the ori would prevent replication entirely; Statement II correctly describes the typical target (a marker gene).', difficulty: 'medium' },
  { id: 'btp-st-12', type: 'statement', question: 'Statement I: Restriction enzymes are named partly based on the bacterial species they were isolated from.\nStatement II: EcoRI is isolated from Escherichia coli.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe restriction enzyme naming conventions and the specific example of EcoRI.', difficulty: 'medium' },
  { id: 'btp-st-13', type: 'statement', question: 'Statement I: Recombinant DNA technology begins with isolating pure DNA before any cutting or cloning.\nStatement II: The final step of the overall process is typically downstream processing to obtain a usable product.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the start and end of the overall rDNA technology pipeline.', difficulty: 'medium' },
  { id: 'btp-st-14', type: 'statement', question: 'Statement I: A vector must be able to replicate independently within the host cell.\nStatement II: A vector must always be larger in size than the host chromosome.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct (independent replication is essential); Statement II is incorrect — vectors like plasmids are typically much SMALLER than the host chromosome.', difficulty: 'medium' },
  { id: 'btp-st-15', type: 'statement', question: 'Statement I: Biolistics (gene gun) is commonly used for introducing DNA into plant cells.\nStatement II: This method relies on high-velocity DNA-coated metal particles penetrating the cell wall.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly describe the biolistic gene delivery method.', difficulty: 'medium' },
  { id: 'btp-st-16', type: 'statement', question: 'Statement I: Restriction enzymes function only on RNA molecules, not DNA.\nStatement II: Restriction enzymes cut DNA at specific palindromic recognition sequences.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — restriction enzymes act on DNA, not RNA; Statement II correctly describes their actual mode of action.', difficulty: 'medium' },
  { id: 'btp-st-17', type: 'statement', question: 'Statement I: An "ori" sequence determines how many copies of a linked plasmid are maintained in the host cell.\nStatement II: All plasmids maintain exactly the same copy number regardless of their ori sequence.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 2, explanation: 'Statement I is correct; Statement II is incorrect — copy number varies depending on the specific ori sequence used.', difficulty: 'medium' },
  { id: 'btp-st-18', type: 'statement', question: 'Statement I: PCR can be used to amplify DNA even when only a very small starting quantity is available.\nStatement II: This makes PCR useful in forensic science and early disease diagnosis.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 0, explanation: 'Both statements correctly capture why PCR is so valuable — high sensitivity from minimal starting material, useful in forensics/diagnostics.', difficulty: 'medium' },
  { id: 'btp-st-19', type: 'statement', question: 'Statement I: A host cell for genetic engineering must always be a bacterium.\nStatement II: Plant and animal cells can also serve as hosts for recombinant DNA technology.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — hosts are not limited to bacteria; Statement II correctly notes that plant and animal cells can serve as hosts too.', difficulty: 'medium' },
  { id: 'btp-st-20', type: 'statement', question: 'Statement I: Elution refers to the process of cutting DNA at a restriction site.\nStatement II: Elution refers to extracting a DNA fragment from an excised gel piece.', options: ['Both correct', 'Both incorrect', 'I correct, II incorrect', 'II correct, I incorrect'], correctIndex: 3, explanation: 'Statement I is incorrect — that describes restriction digestion, not elution; Statement II correctly defines elution.', difficulty: 'medium' },

  // ---- "How many of the following are correct" ----
  { id: 'btp-hm-1', type: 'statement', question: 'How many of the following are considered essential "tools" of recombinant DNA technology?\nRestriction enzymes, Cloning vectors, A competent host organism, Chlorophyll pigments', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Restriction enzymes, vectors, and a competent host are the three essential tools; chlorophyll pigments are unrelated.', difficulty: 'medium' },
  { id: 'btp-hm-2', type: 'statement', question: 'How many of the following are steps typically involved in the overall process of recombinant DNA technology?\nIsolation of DNA, Cutting DNA with restriction enzymes, Amplification via PCR, Ligation into a vector, Transfer of rDNA into a host, Culturing and downstream processing', options: ['Three', 'Four', 'Five', 'All six'], correctIndex: 3, explanation: 'All six steps listed are legitimate parts of the standard rDNA technology workflow.', difficulty: 'medium' },
  { id: 'btp-hm-3', type: 'statement', question: 'How many of the following are features typically found in the pBR322 plasmid vector?\nOrigin of replication, Ampicillin resistance gene, Tetracycline resistance gene, Unique restriction sites for cloning, A functioning nucleus', options: ['Two', 'Three', 'Four', 'Five'], correctIndex: 2, explanation: 'Ori, ampR, tetR, and cloning sites are all genuine pBR322 features; plasmids, being prokaryotic DNA elements, have no nucleus.', difficulty: 'medium' },
  { id: 'btp-hm-4', type: 'statement', question: 'How many of the following are valid methods for introducing foreign DNA into a host cell?\nMicro-injection, Biolistics (gene gun), Using a disarmed vector like Agrobacterium Ti plasmid, CaCl2-mediated transformation', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are legitimate, commonly used gene-delivery methods, appropriate to different host cell types.', difficulty: 'medium' },
  { id: 'btp-hm-5', type: 'statement', question: 'How many of the following are correctly the three basic steps of a single PCR cycle?\nDenaturation, Annealing, Extension, Ligation', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Denaturation, annealing, and extension are the three PCR cycle steps; ligation is a separate process, unrelated to PCR itself.', difficulty: 'medium' },
  { id: 'btp-hm-6', type: 'statement', question: 'How many of the following are true about restriction endonucleases?\nThey cut DNA at specific palindromic sequences, They were discovered through studies of bacteriophage resistance, They always produce blunt ends only, Different enzymes are named partly after the bacteria they came from', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: "Palindromic recognition, discovery via phage-resistance studies, and naming conventions are correct; restriction enzymes do NOT always produce blunt ends — many produce sticky ends.", difficulty: 'medium' },
  { id: 'btp-hm-7', type: 'statement', question: 'How many of the following are functions/components of a typical stirred-tank bioreactor?\nAn agitator system, An oxygen delivery system, A foam control mechanism, A system for temperature control', options: ['One', 'Two', 'Three', 'All four'], correctIndex: 3, explanation: 'All four are standard functional components/considerations built into stirred-tank bioreactor design.', difficulty: 'medium' },
  { id: 'btp-hm-8', type: 'statement', question: 'How many of the following steps belong to downstream processing?\nSeparation of the product, Purification of the product, Formulation with preservatives, Isolation of the original gene from source DNA', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: "Separation, purification, and formulation are downstream processing steps; isolating the original gene is an UPSTREAM step, occurring long before downstream processing.", difficulty: 'medium' },
  { id: 'btp-hm-9', type: 'statement', question: 'How many of the following are true regarding gel electrophoresis of DNA?\nDNA fragments are separated by size, Smaller fragments move faster, The gel is typically made of agarose, DNA bands are directly visible without any staining', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Size-based separation, faster movement of smaller fragments, and agarose gel composition are correct; DNA bands are NOT directly visible — staining (e.g., ethidium bromide) and UV light are required.', difficulty: 'medium' },
  { id: 'btp-hm-10', type: 'statement', question: 'How many of the following organisms/sources are correctly matched to a biotechnology tool derived from them?\nThermus aquaticus → Taq polymerase, Escherichia coli → EcoRI, Agrobacterium tumefaciens → Ti plasmid, Bacillus thuringiensis → Restriction enzymes generally used in cloning vectors', options: ['One', 'Two', 'Three', 'Four'], correctIndex: 2, explanation: 'Taq polymerase, EcoRI, and Ti plasmid are correctly matched to their sources; Bacillus thuringiensis is mainly known for its insecticidal Bt toxin, not for restriction enzymes used in cloning.', difficulty: 'hard' },
];
